{
  "implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    fixed_point = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            name = p['name']
            old = p['old']
            new = p['new']
            pos = text.find(old)
            if pos != -1:
                text = text[:pos] + new + text[pos+len(old):]
                applications.append(name)
                changed = True
        if not changed:
            fixed_point = True
            break
    else:
        fixed_point = False
    return {
        'applications': applications,
        'fixed_point': fixed_point,
        'text': text
    }"
}
